// WrapLocalDevHookCommand wraps a local-dev "go run" hook invocation so that it
// tolerates a project that does not compile (e.g. mid merge-conflict-fix).
//
// On demand "go run" rebuilds the CLI from source; if the tree is broken the
// build fails and the hook silently does nothing. The wrapper first probes the
// build with "go build -o /dev/null", running via "go run" only when it
// succeeds, and otherwise falling back to the entire binary on PATH. When the
// project does not build and no binary is on PATH, the wrapper exits 0 so the
// surrounding git/agent operation is not blocked.
//
// buildTarget is the path passed to "go build" (e.g.
// "${CLAUDE_PROJECT_DIR}/cmd/entire/main.go"). goRunCommand is the full
// "go run ..." invocation used when the build succeeds. fallbackCommand is the
// "entire ..." invocation used when the build fails but the binary is on PATH.
//
// This form uses exec and reads its payload from stdin, so it is unsuitable for
// hooks that depend on positional parameters ($1, $2) — see strategy git hooks
// for that case.
func WrapLocalDevHookCommand(buildTarget, goRunCommand, fallbackCommand string) string {
	return fmt.Sprintf(
		`sh -c 'if go build -o /dev/null %s >/dev/null 2>&1; then exec %s; elif command -v entire >/dev/null 2>&1; then exec %s; fi'`,
		buildTarget,
		goRunCommand,
		fallbackCommand,
	)
}

const productionHookWrapperPrefix = `sh -c 'if ! command -v entire >/dev/null 2>&1; then `

const localDevHookWrapperPrefix = `sh -c 'if go build `

