	return fmt.Sprintf(
		`sh -c 'if go build -o /dev/null %s >/dev/null 2>&1; then exec %s; elif command -v entire >/dev/null 2>&1; then exec %s; fi'`,
		buildTarget,
		goRunCommand,
		fallbackCommand,
	)
}

