func TestWrapLocalDevHookCommand(t *testing.T) {
	t.Parallel()

	buildTarget := "${CLAUDE_PROJECT_DIR}/cmd/entire/main.go"
	goRun := "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code stop"
	fallback := "entire hooks claude-code stop"

	command := WrapLocalDevHookCommand(buildTarget, goRun, fallback)

