func TestInstallGitHook_LocalDevFallsBackToBinaryWhenBuildFails(t *testing.T) {
	t.Parallel()

	shPath := requireShell(t)
	goPath, err := exec.LookPath("go")
	if err != nil {
		t.Skip("go not available")
	}

	tempDir := t.TempDir() // no ./cmd/entire/main.go here, so `go build` fails
	binDir := t.TempDir()
	msgFile := filepath.Join(tempDir, "COMMIT_EDITMSG")
	if err := os.WriteFile(msgFile, []byte("commit message\n"), 0o600); err != nil {
		t.Fatalf("failed to write commit message: %v", err)
	}

	markerFile := filepath.Join(tempDir, "entire-ran")
	fakeEntire := "#!/bin/sh\nprintf 'ran\\n' > " + shellQuote(markerFile) + "\n"
	if err := os.WriteFile(filepath.Join(binDir, "entire"), []byte(fakeEntire), 0o755); err != nil {
		t.Fatalf("failed to write fake entire: %v", err)
	}

	hook := findHookSpec(t, buildHookSpecs(localDevHookCmdPrefix), "prepare-commit-msg")
	hookPath := filepath.Join(tempDir, "prepare-commit-msg")
	if err := os.WriteFile(hookPath, []byte(hook.content), 0o755); err != nil {
		t.Fatalf("failed to write hook: %v", err)
	}

	cmd := exec.CommandContext(context.Background(), shPath, hookPath, msgFile, "message")
	cmd.Dir = tempDir
	cmd.Env = append(envWithPath(binDir+string(os.PathListSeparator)+filepath.Dir(goPath)), "GOCACHE="+t.TempDir())
