	if err != nil {
		t.Fatalf("local-dev hook should not fail the commit when the build is broken: %v\n%s", err, output)
	}

	if _, err := os.Stat(markerFile); err != nil {
		t.Fatalf("expected fallback to the entire binary on PATH when the build fails, marker missing: %v\noutput:\n%s", err, output)
	}
}

