        "matcher": "Task",
        "hooks": [
          {
            "type": "command",
            "command": "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code post-task"
          }
        ]
      },
      {
        "matcher": "TodoWrite",
